INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','present-simple','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"present-simple","title":"Present simple","level":"A1","order":10,"summary":"Talk about regular activities and practise agreement, negatives, questions and base forms.","learningGoals":["Habits and facts","Spelling","Do and does"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Habits and facts","explanation":"Use the present simple for routines and general facts. With I, you, we and they, use the base verb. Most singular third-person subjects add -s.","examples":["We cycle to college.","The guide explains the route."]},{"title":"Spelling","explanation":"Some verbs add -es. A consonant followed by y usually changes to -ies; a vowel followed by y keeps the y.","examples":["She carries the equipment.","He plays chess."]},{"title":"Do and does","explanation":"Use do or does for questions, and do not or does not for negatives. The main verb then returns to its base form.","examples":["Does the driver stop here?","We do not work on Sundays."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-present","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["The present simple presents a habit, a general fact or a situation viewed as stable. It does not always mean that an action is happening this second. In She works at a café, the job is the relevant fact; she may be at home right now. Look at both the time meaning and the subject before choosing a form."],"rules":[{"title":"Habits and facts","explanation":"Use the present simple for routines and general facts. With I, you, we and they, use the base verb. Most singular third-person subjects add -s.","examples":["We cycle to college.","The guide explains the route.","The guide explain**s** the route every morning."],"pattern":"I **work** / She work**s**","paragraphs":["The ending **-s is added to the verb**, not to the subject. It appears with third-person singular subjects such as he, she, it and the driver. I and you do not take it. A plural noun subject also uses the base verb: The drivers work."],"id":"present-simple-foundation-1","domain":"verbs","referenceIds":["bc-present","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Spelling","explanation":"Some verbs add -es. A consonant followed by y usually changes to -ies; a vowel followed by y keeps the y.","examples":["She carries the equipment.","He plays chess.","**Does** the guide **explain** the route?"],"pattern":"watch → watch**es** · study → stud**ies** · play → play**s**","paragraphs":["Learn spelling with the verb. After a consonant + y, change y to -ies: carry → carries. After a vowel + y, keep y: enjoy → enjoys. Go → goes and do → does add -es; have → has is irregular. The pronunciation of the ending also varies."],"id":"present-simple-foundation-2","domain":"verbs","referenceIds":["bc-present","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Do and does","explanation":"Use do or does for questions, and do not or does not for negatives. The main verb then returns to its base form.","examples":["Does the driver stop here?","We do not work on Sundays.","The guide **doesn’t explain** the route on Sundays."],"pattern":"**Does** she **work**? / She **does not work**.","paragraphs":["In a question or negative, the auxiliary do/does carries the agreement. That is why Does she works? is incorrect: it marks agreement twice. Keep the main verb at its base: Does she work? The same principle applies after doesn’t."],"id":"present-simple-foundation-3","domain":"verbs","referenceIds":["bc-present","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Frequency adverbs normally precede the lexical verb: she usually works. Present simple also describes published schedules: The train leaves at six. Stative verbs such as know commonly use simple rather than continuous forms. Present simple is not restricted to repeated visible actions.","examples":["The guide explain**s** the route every morning.","**Does** the guide **explain** the route?","The guide **doesn’t explain** the route on Sundays."],"id":"present-simple-foundation-4","domain":"verbs","referenceIds":["bc-present","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"verbs","id":"tense-aspect-time","title":"Tense, aspect and time are different dimensions","explanation":"Tense is a grammatical form; time is when a situation is located; aspect is how the speaker views its course. English present and past forms combine with perfect and progressive constructions. Future meaning uses several constructions. A familiar classroom tense name is useful shorthand, but it does not determine meaning independently of context.","pattern":"**past form** ≠ always **past time**","examples":["The train **leaves tomorrow**.","If I **knew** the answer now, I would tell you."],"commonMistakes":["Calling will a future tense is a common teaching convention. It does not mean every future event must use will or every use of will concerns future time."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"inflection","id":"verb-form-paradigms","title":"The five main verb forms and irregular families","explanation":"Most lexical verbs have a base, an -s form, a past form, a past participle and an -ing form. Some share spellings; others differ. Be has additional person/number forms. The auxiliary construction tells you which form to use. A dictionary’s principal parts are the right reference for lexical irregularities.","pattern":"**write · writes · wrote · written · writing**","examples":["**cut · cuts · cut · cut · cutting**","**go · goes · went · gone · going**"],"commonMistakes":["Past and past participle are separate categories even when they look alike: I worked / I have worked; I went / I have gone."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["I **work** / She work**s**","watch → watch**es** · study → stud**ies** · play → play**s**","**Does** she **work**? / She **does not work**."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["have-got"],"readingReferenceIds":["bc-present","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='present-simple'
